<script setup>
import {ref,watch} from 'vue';
import PagedRecords from './PagedRecords.vue';
import ListPager from './ListPager.vue';
import {s,canEdit,canAdmin,api,loadSources,sourceEnabled,resolveConflict,run,stageFile,stageSheet,aiMapping,previewData,commitData,toggleSync,sync,dateText,number,modeLabel} from './store';
const props=defineProps({mobile:Boolean});
const importOpen=ref(!!s.stage),inputKind=ref('file'),advanced=ref(false),tab=ref('sources');
watch(()=>s.stage,v=>{if(v)importOpen.value=true;});
watch(()=>s.conflicts?.total,v=>{if(!v)tab.value='sources';else if(s.message)tab.value='conflicts';});
async function conflictPage(page,pageSize=s.conflicts.pageSize){s.conflicts=await api('/api/events/'+s.event.id+'/conflicts?page='+page+'&pageSize='+pageSize);}
async function importFile(files){await stageFile(files);if(!s.stage)importOpen.value=false;}
async function importSheet(){await stageSheet();if(!s.stage)importOpen.value=false;}
async function commit(){await commitData();if(!s.stage)importOpen.value=false;}
function addSource(){inputKind.value='file';importOpen.value=true;}
</script><template><section class="stack"><div v-if="!canEdit" class="notice">Bạn có quyền xem. Liên hệ Admin sự kiện để được cấp quyền chỉnh sửa.</div><div class="toolbar"><MTabs v-model="tab" :tabs="[{key:'sources',label:'Nguồn dữ liệu ('+s.eventSources.length+')'},...(canAdmin&&s.conflicts?.total?[{key:'conflicts',label:'Cần đối chiếu ('+s.conflicts.total+')'}]:[])]"/><MButton v-if="canEdit" variant="primary" @click="addSource">Thêm nguồn dữ liệu</MButton></div><div v-if="tab==='sources'" class="card stack"><div class="toolbar"><h3>Nguồn đã kết nối</h3><MButton v-if="canEdit&&s.eventSources.some(v=>v.enabled)" variant="secondary" :loading="s.busy" @click="run(sync)">Đồng bộ ngay</MButton></div><p v-if="!s.eventSources.length" class="muted">Chưa có nguồn dữ liệu.</p><PagedRecords v-else :rows="s.eventSources" v-slot="{rows}"><article v-for="source in rows" :key="source.id" class="source-entry"><div class="toolbar"><strong>{{source.label}}</strong><span>{{source.mode==='auto'?'Theo từng dòng':source.mode==='online'?'Online':'Offline'}}</span></div><div class="row"><span class="muted">{{source.kind==='sheet'?'Google Sheet':'File'}} · {{dateText(source.synced_at)}}</span><MCheckbox v-if="source.kind==='sheet'" :model-value="source.enabled" :disabled="!canAdmin||s.busy" label="Tự đồng bộ" @update:model-value="run(()=>sourceEnabled(source,$event))"/></div><p v-if="source.error" class="error">{{source.error}}</p></article></PagedRecords></div>
<div v-if="tab==='conflicts'&&s.conflicts?.total&&canAdmin" class="card stack"><h3>Khách cần đối chiếu ({{s.conflicts.total}})</h3><p class="muted">Các dòng này chưa cộng vào báo cáo. Chọn hồ sơ cần cập nhật hoặc xác nhận là khách khác.</p><article v-for="item in s.conflicts.rows" :key="item.id" class="source-entry stack"><strong>{{modeLabel(item.data.attendance_mode)}} · {{item.data.name||'Chưa có tên'}} · {{item.data.phone||item.data.email||'—'}}</strong><p>{{item.reason}}</p><div class="conflict-candidates"><article v-for="candidate in item.candidates" :key="candidate.id" class="conflict-candidate"><div class="toolbar"><MTag color="brand">{{modeLabel(candidate.data.attendance_mode)}}</MTag><span class="muted">Hồ sơ {{candidate.id.slice(0,8)}}</span></div><strong>{{candidate.data.name||'Chưa có tên'}}</strong><span>{{candidate.data.phone||candidate.data.email||'Chưa có liên hệ'}}</span><span class="muted">{{[candidate.data.company,candidate.data.department,candidate.data.email].filter(Boolean).join(' · ')||'Chưa có thông tin bổ sung'}}</span><MButton variant="secondary" :loading="s.busy" @click="run(()=>resolveConflict(item,candidate.id))">Cập nhật khách {{modeLabel(candidate.data.attendance_mode)}} · {{candidate.id.slice(0,8)}}</MButton></article></div><MButton variant="secondary" :loading="s.busy" @click="run(()=>resolveConflict(item,null))">Là khách khác — tạo hồ sơ riêng</MButton></article><ListPager :page="s.conflicts.page" :page-size="s.conflicts.pageSize" :total="s.conflicts.total" @update:page-size="run(()=>conflictPage(1,$event))" @update:page="run(async()=>s.conflicts=await api('/api/events/'+s.event.id+'/conflicts?page='+$event+'&pageSize='+s.conflicts.pageSize))"/></div>
<MDialog v-if="canEdit" v-model="importOpen" :presentation="mobile?'sheet':'dialog'" :width="900" :title="s.stage?'Kiểm tra dữ liệu nhập':'Thêm nguồn dữ liệu'"><div class="stack" :class="{'mds-mobile-app':mobile}"><p v-if="s.error" class="error" role="alert">{{s.error}}</p><div v-if="!s.stage" class="stack"><p class="muted">Mỗi nguồn được cập nhật riêng. Nhập lại không xóa khách hay ghi đè lịch sử liên hệ. Trường thiếu được để trống.</p><div class="grid-form"><label class="field">Nhập vào nhóm<MSelect v-model="s.importMode" :options="[{value:'auto',label:'Theo từng dòng — thiếu thì Chưa xác định'},{value:'online',label:'Online'},{value:'offline',label:'Offline'}]"/></label><label class="field">Loại danh sách<MSelect v-model="s.registrationStatus" :options="[{value:'registered',label:'Khách đã đăng ký'},{value:'invited',label:'Danh sách mời — chưa đăng ký'}]"/></label></div><MButton variant="link" :aria-expanded="advanced" @click="advanced=!advanced">{{advanced?'Thu gọn tùy chọn':'Tùy chọn đọc dữ liệu'}}</MButton><div v-if="advanced" class="grid-form"><label class="field">Tên tab (* để đọc tất cả các phòng / nhóm)<MInput v-model="s.sheetName" /></label><label class="field">Dòng tiêu đề (0 để tự nhận diện)<MInput v-model="s.headerRow" /></label></div><MTabs v-if="canAdmin" v-model="inputKind" :tabs="[{key:'file',label:'File Excel / CSV'},{key:'sheet',label:'Google Sheet'}]"/><MUpload v-if="inputKind==='file'" accept=".xlsx,.csv" :multiple="false" :max-size-m-b="10" :disabled="s.busy" label="Chọn file Excel hoặc CSV" @select-files="run(()=>importFile($event))" @oversized="s.error='File tối đa 10 MB.'" /><label v-if="inputKind==='sheet'&&canAdmin" class="field">Link Google Sheet<MInput v-model="s.sheetUrl" placeholder="https://docs.google.com/spreadsheets/..." /></label><div v-if="inputKind==='sheet'&&canAdmin" class="row justify-end"><MButton variant="primary" :loading="s.busy" @click="run(importSheet)">Nhập và tổng hợp</MButton></div></div>
<div v-if="s.stage&&canEdit" class="stack"><div class="toolbar"><h3>Ghép cột · {{number(s.stage.count)}} dòng</h3><MButton variant="secondary" :loading="s.busy" @click="run(aiMapping)">Gợi ý bằng Gemini</MButton></div><p class="muted">{{s.stage.discovery?.notice||'Đã nhận diện các cột nguồn khách.'}}</p><div class="grid-form"><label v-for="(label,key) in s.user.fields" :key="key" class="field">{{label}}<MCombobox v-model="s.mapping[key]" :options="[{label:'Không có cột',value:''},...s.stage.headers.map(h=>({value:h,label:h}))]" @change="s.preview=null" /></label></div><label class="field">Các cột dùng lọc nguồn, nhân viên (tối đa 12)<MCombobox v-model="s.sourceColumns" multiple :options="s.stage.headers.map(h=>({value:h,label:h}))" @change="s.preview=null" /></label><MCheckbox v-model="s.autoSync" label="Tự đồng bộ nếu nguồn là Google Sheet"/><div v-if="s.preview" class="notice">Xem trước: {{number(s.preview.summary.total)}} đăng ký, {{number(s.preview.summary.clevel)}} C-Level, {{number(s.preview.quality.invalidDates)}} khách thiếu ngày hợp lệ. Trường không có được giữ trống.</div><div class="row justify-end"><MButton variant="secondary" :loading="s.busy" @click="run(previewData)">Kiểm tra dữ liệu</MButton><MButton variant="primary" :loading="s.busy" :disabled="!s.preview" @click="run(commit)">Nhập dữ liệu</MButton></div></div></div><template #footer><MButton variant="secondary" @click="importOpen=false">Đóng</MButton></template></MDialog></section></template>
